const starterIdeas=['ARISE','BREAD','CLOUD','GRACE','HOUSE','OCEAN','PLANT','SHINE','STONE','TRAIN'];
document.querySelector('#ideaAction').onclick=()=>{document.querySelector('#quickHelpDialog').close();notify(`Try starting with ${starterIdeas[puzzle%starterIdeas.length]}`)};

const themeNames=['classic','ocean','forest'];
function setTheme(theme){theme=themeNames.includes(theme)?theme:'classic';document.body.classList.remove('theme-ocean','theme-forest');if(theme!=='classic')document.body.classList.add(`theme-${theme}`);prefs.theme=theme;localStorage.setItem('daily-letter-prefs',JSON.stringify(prefs));document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme===theme))}
setTheme(prefs.theme||'classic');document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>setTheme(b.dataset.theme));

const sessionKey='daily-letter-session';let profile=null,profileGameStats=null;
async function api(action,data){
  const response=await fetch('/.netlify/functions/api?action='+encodeURIComponent(action),{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});
  let result={};try{result=await response.json()}catch{}
  if(!response.ok)throw new Error(result.error||'Something went wrong. Please try again.');
  return result;
}
function signedIn(){return !!profile}
function paintProfile(){const active=signedIn();if(!active&&document.querySelector('#editProfileForm'))setProfileEdit(false);document.querySelector('#signedOutView').hidden=active;document.querySelector('#signedInView').hidden=!active;document.querySelector('#accountLabel').textContent=active?'@'+profile.username:'Account';const initial=active?profile.firstName.trim().charAt(0).toUpperCase():'A';document.querySelector('#accountAvatar').textContent=initial;document.querySelector('#profileAvatar').textContent=initial;if(active){const s=profileGameStats||{played:stats.played,wins:stats.wins,streak:stats.streak,best:stats.best};document.querySelector('#profileGreeting').textContent=`Hello, ${profile.firstName}!`;document.querySelector('#profileUsernameDisplay').textContent=`Player ID: @${profile.username}`;document.querySelector('#profileFullName').textContent=[profile.firstName,profile.lastName].filter(Boolean).join(' ');document.querySelector('#profileAgeDisplay').textContent=profile.age||'—';document.querySelector('#profileEmailDisplay').textContent=profile.email||'—';document.querySelector('#profilePhoneDisplay').textContent=profile.phone||'—';document.querySelector('#profileAddressDisplay').textContent=[profile.street,profile.city,profile.state,profile.zip].filter(Boolean).join(', ')||'—';document.querySelector('#profileStreak').textContent=s.streak||0;document.querySelector('#profileBest').textContent=s.best||0;document.querySelector('#profilePlayed').textContent=s.played||0;document.querySelector('#profileWinRate').textContent=(s.played?Math.round((s.wins||0)/s.played*100):0)+'%'}paintHomeStreak()}
document.querySelector('#accountButton').onclick=()=>{paintProfile();openDialog('accountDialog')};
function makeUsername(){const first=document.querySelector('#profileFirstName').value||'player',last=document.querySelector('#profileLastName').value||'';const base=(first+last).toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,16)||'player';return `${base}${Math.floor(100+Math.random()*900)}`}
function suggestUsername(){const field=document.querySelector('#profileUsername');if(!field.value)field.value=makeUsername()}
document.querySelector('#generateUsernameButton').onclick=()=>{document.querySelector('#profileUsername').value=makeUsername();document.querySelector('#profileUsername').focus()};
['#profileFirstName','#profileLastName'].forEach(selector=>document.querySelector(selector).addEventListener('blur',suggestUsername));
document.querySelector('#profilePhone').addEventListener('input',e=>{const digits=e.target.value.replace(/\D/g,'').slice(0,10);e.target.value=digits.length>6?`(${digits.slice(0,3)}) ${digits.slice(3,6)}-${digits.slice(6)}`:digits.length>3?`(${digits.slice(0,3)}) ${digits.slice(3)}`:digits});
function showRegisterStatus(text,type=''){const box=document.querySelector('#registerStatus');box.textContent=text;box.className='form-status'+(type?' '+type:'')}
function setFormBusy(form,busy){
  const label=form.querySelector('.button-label');
  if(label){
    if(busy&&!form.classList.contains('is-busy'))label.dataset.idleLabel=label.textContent;
    if(busy&&form.id==='editProfileForm')label.textContent='Saving…';
    if(!busy&&!form.classList.contains('is-success'))label.textContent=label.dataset.idleLabel||label.textContent;
  }
  form.classList.toggle('is-busy',busy);
  form.setAttribute('aria-busy',String(busy));
  form.querySelectorAll('button,input,select').forEach(el=>el.disabled=busy);
}
document.querySelector('#registerForm').addEventListener('invalid',e=>{e.target.classList.add('field-error');showRegisterStatus('Please complete the highlighted field.','error')},true);
document.querySelectorAll('#registerForm input,#registerForm select').forEach(field=>field.addEventListener('input',()=>{field.classList.remove('field-error');if(document.querySelector('#registerStatus').classList.contains('error'))showRegisterStatus('')}));
document.querySelector('#registerForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;showRegisterStatus('Securely creating your Player ID…','working');setFormBusy(form,true);try{const firstName=document.querySelector('#profileFirstName').value.trim(),lastName=document.querySelector('#profileLastName').value.trim();const result=await api('register',{firstName,lastName,email:document.querySelector('#profileEmail').value.trim(),age:Number(document.querySelector('#profileAge').value),phone:document.querySelector('#profilePhone').value.trim(),street:document.querySelector('#profileStreet').value.trim(),city:document.querySelector('#profileCity').value.trim(),state:document.querySelector('#profileState').value,zip:document.querySelector('#profileZip').value.trim(),username:document.querySelector('#profileUsername').value.trim(),password:document.querySelector('#profilePassword').value,consent:document.querySelector('#profileConsent').checked});profile=result.profile;profileGameStats=result.stats||{played:0,wins:0,streak:0,best:0};paintProfile();form.classList.add('is-success');form.querySelector('.button-label').textContent='Account created!';showRegisterStatus(`Welcome, @${profile.username}! Your account is ready.`,'success');setTimeout(()=>{document.querySelector('#accountDialog').close();notify('Player ID created — welcome!')},700)}catch(error){showRegisterStatus(error.message,'error');setFormBusy(form,false)}};
document.querySelector('#showLoginButton').onclick=()=>{document.querySelector('#registerForm').hidden=true;document.querySelector('#showLoginButton').hidden=true;document.querySelector('#loginForm').hidden=false};document.querySelector('#showRegisterButton').onclick=()=>{document.querySelector('#loginForm').hidden=true;document.querySelector('#registerForm').hidden=false;document.querySelector('#showLoginButton').hidden=false};
document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;setFormBusy(form,true);try{const result=await api('login',{username:document.querySelector('#loginUsername').value.trim(),password:document.querySelector('#loginPassword').value});profile=result.profile;profileGameStats=result.stats||null;paintProfile();document.querySelector('#accountDialog').close();notify('Welcome back!')}catch(error){notify(error.message)}finally{setFormBusy(form,false)}};
document.querySelector('#logoutButton').onclick=async()=>{try{await api('logout',{})}catch{}profile=null;profileGameStats=null;paintProfile();notify('Logged out')};
const editForm=document.querySelector('#editProfileForm'),editButton=document.querySelector('#editProfileButton');
const editState=document.querySelector('#editState');editState.innerHTML=document.querySelector('#profileState').innerHTML;
function phoneDigits(value){return String(value||'').replace(/^\+?1\s*/,'').replace(/\D/g,'').slice(0,10)}
function formatPhone(value){const digits=phoneDigits(value);return digits.length>6?`(${digits.slice(0,3)}) ${digits.slice(3,6)}-${digits.slice(6)}`:digits.length>3?`(${digits.slice(0,3)}) ${digits.slice(3)}`:digits}
function setProfileEdit(open){document.querySelector('#accountDialog').classList.toggle('is-editing',open);editForm.hidden=!open;editButton.hidden=open;document.querySelector('.profile-details').hidden=open;if(open){document.querySelector('#editFirstName').value=profile.firstName||'';document.querySelector('#editLastName').value=profile.lastName||'';document.querySelector('#editEmail').value=profile.email||'';document.querySelector('#editAge').value=profile.age||'';document.querySelector('#editPhone').value=formatPhone(profile.phone);document.querySelector('#editStreet').value=profile.street||'';document.querySelector('#editCity').value=profile.city||'';editState.value=profile.state||'';document.querySelector('#editZip').value=profile.zip||'';document.querySelector('#editUsernameDisplay').textContent='@'+profile.username;document.querySelector('#editProfileStatus').textContent='';document.querySelector('#editProfileStatus').className='form-status';document.querySelector('#profileEditFields').scrollTop=0;document.querySelector('#editFirstName').focus({preventScroll:true})}else if(profile){editButton.focus({preventScroll:true})}}
editButton.onclick=()=>setProfileEdit(true);document.querySelector('#cancelProfileEdit').onclick=()=>setProfileEdit(false);
document.querySelector('#editPhone').addEventListener('input',e=>e.target.value=formatPhone(e.target.value));
editForm.onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const status=document.querySelector('#editProfileStatus');status.textContent='Saving your changes…';status.className='form-status working';setFormBusy(form,true);try{const result=await api('update-profile',{firstName:document.querySelector('#editFirstName').value.trim(),lastName:document.querySelector('#editLastName').value.trim(),email:document.querySelector('#editEmail').value.trim(),age:Number(document.querySelector('#editAge').value),phone:document.querySelector('#editPhone').value.trim(),street:document.querySelector('#editStreet').value.trim(),city:document.querySelector('#editCity').value.trim(),state:editState.value,zip:document.querySelector('#editZip').value.trim()});profile=result.profile;paintProfile();status.textContent='Your details were saved.';status.className='form-status success';setTimeout(()=>setProfileEdit(false),550)}catch(error){status.textContent=error.message;status.className='form-status error'}finally{setFormBusy(form,false)}};
document.querySelector('#openSettingsFromAccount').onclick=()=>{document.querySelector('#accountDialog').close();openDialog('settingsDialog')};
async function recordResult(){if(!profile||!state.ended)return;try{const result=await api('result',{puzzleNumber:puzzle,guesses:state.guesses.length,won:state.won});profileGameStats=result.stats||profileGameStats;paintProfile();loadLeaderboard()}catch{}}
function paintHomeStreak(){const value=profileGameStats?.streak||0;document.querySelector('#homeStreak').textContent=value+' '+(value===1?'day':'days');document.querySelector('#homeStreakMessage').textContent=profile?(value?'Keep it going — play today!':'Solve today’s puzzle to begin'):'Sign in to track your streak'}
function escapeText(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
async function loadLeaderboard(){const list=document.querySelector('#leaderboardList'),samples=Array.isArray(window.LEADERBOARD_PLAYERS)?window.LEADERBOARD_PLAYERS:[];let live=[];try{const result=await api('leaderboard');live=result.players||[]}catch{}const seen=new Set(live.map(p=>String(p.username).toLowerCase()));const players=[...live,...samples.filter(p=>!seen.has(String(p.username).toLowerCase())).map(p=>({...p,sample:true}))].slice(0,100);if(!players.length){list.innerHTML='<li class="leaderboard-empty">Complete a puzzle to become the first ranked player.</li>';return}list.innerHTML=players.map((p,i)=>`<li class="${profile&&p.username===profile.username?'is-current':''}"><span class="rank-number">${i+1}</span><span class="rank-avatar">${escapeText((p.name||p.username).charAt(0).toUpperCase())}</span><span class="rank-player"><strong>${escapeText(p.name)}${p.sample?' <em>Sample</em>':''}</strong><small>@${escapeText(p.username)} · ${p.streak} day streak</small></span><strong class="rank-score">${p.wins}</strong></li>`).join('')}
async function startAccount(){try{const result=await api('me');profile=result.profile||null;profileGameStats=result.stats||null}catch{profile=null;profileGameStats=null}paintProfile();loadLeaderboard();if(!profile)setTimeout(()=>openDialog('accountDialog'),250);else{api('heartbeat',{}).catch(()=>{});setInterval(()=>api('heartbeat',{}).catch(()=>{}),120000)}}
startAccount();
